import{_ as e,o as i,c as a,a4 as t}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"AI 编程工具的 Shell 行为分析","description":"","frontmatter":{"title":"AI 编程工具的 Shell 行为分析","date":"2026-06-26T00:00:00.000Z"},"headers":[],"relativePath":"posts/AI 编程工具 Shell 行为分析.md","filePath":"posts/AI 编程工具 Shell 行为分析.md"}'),l={name:"posts/AI 编程工具 Shell 行为分析.md"};function d(n,s,h,o,r,p){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="ai-编程工具的-shell-行为分析" tabindex="-1">AI 编程工具的 Shell 行为分析 <a class="header-anchor" href="#ai-编程工具的-shell-行为分析" aria-label="Permalink to &quot;AI 编程工具的 Shell 行为分析&quot;">​</a></h1><h2 id="测试环境" tabindex="-1">测试环境 <a class="header-anchor" href="#测试环境" aria-label="Permalink to &quot;测试环境&quot;">​</a></h2><ul><li>Windows 11</li><li>PowerShell 7.x</li><li>Git Bash (MSYS2)</li><li>WSL2 Ubuntu</li></ul><h2 id="结论速查" tabindex="-1">结论速查 <a class="header-anchor" href="#结论速查" aria-label="Permalink to &quot;结论速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>PowerShell 启动</th><th>Git Bash 启动</th><th>WSL bash 启动</th></tr></thead><tbody><tr><td>Claude Code</td><td>Git Bash</td><td>Git Bash</td><td>WSL bash</td></tr><tr><td>Codex</td><td>PowerShell</td><td>Git Bash</td><td>WSL bash</td></tr><tr><td>OpenCode</td><td>PowerShell</td><td>Git Bash</td><td>WSL bash</td></tr></tbody></table><p><strong>Claude Code 特殊：在 Windows 上永远用 bash，不用 PowerShell。</strong></p><h2 id="详细分析" tabindex="-1">详细分析 <a class="header-anchor" href="#详细分析" aria-label="Permalink to &quot;详细分析&quot;">​</a></h2><h3 id="claude-code-anthropic" tabindex="-1">Claude Code (Anthropic) <a class="header-anchor" href="#claude-code-anthropic" aria-label="Permalink to &quot;Claude Code (Anthropic)&quot;">​</a></h3><p><strong>安装方式：</strong> npm 全局安装，实际是编译好的原生 <code>claude.exe</code>（245MB）</p><p><strong>Shell 选择逻辑：</strong></p><ul><li>Windows 上强制使用 bash</li><li>优先找 Git Bash (<code>C:\\Program Files\\Git\\bin\\bash.exe</code>)</li><li>如果从 WSL 启动，用 WSL 的 <code>/bin/bash</code></li><li>不使用 PowerShell</li></ul><p><strong>证据：</strong> <code>~/.claude/shell-snapshots/</code> 目录下有 bash snapshot 文件，内容是标准 bash 语法（<code>unalias</code>、<code>shopt</code>、<code>OSTYPE==&quot;msys&quot;</code>）</p><p><strong>启动脚本：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>claude.cmd → claude.exe（原生二进制）</span></span></code></pre></div><h3 id="codex-openai" tabindex="-1">Codex (OpenAI) <a class="header-anchor" href="#codex-openai" aria-label="Permalink to &quot;Codex (OpenAI)&quot;">​</a></h3><p><strong>安装方式：</strong> npm 全局安装，Node.js 脚本 + Rust 编译的 native binding</p><p><strong>Shell 选择逻辑：</strong></p><ul><li>检查 <code>SHELL</code> 环境变量</li><li>Windows 没有 <code>SHELL</code> 变量，默认用 <code>powershell.exe</code></li><li>WSL 里 <code>SHELL=/bin/bash</code>，就用 bash</li></ul><p><strong>启动脚本：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>codex.cmd → node codex.js → @openai/codex-win32-x64 (Rust native)</span></span></code></pre></div><p><strong>配置文件：</strong> <code>~/.codex/config.toml</code></p><h3 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h3><p><strong>安装方式：</strong> Go 编译的 CLI 工具</p><p><strong>Shell 选择逻辑：</strong></p><ul><li>使用当前终端的 shell</li><li>PowerShell 启动 → 用 PowerShell</li><li>WSL bash 启动 → 用 bash</li><li>Git Bash 启动 → 用 Git Bash</li></ul><p><strong>启动方式：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>opencode（直接执行）</span></span></code></pre></div><h2 id="如何强制使用-wsl-shell" tabindex="-1">如何强制使用 WSL Shell <a class="header-anchor" href="#如何强制使用-wsl-shell" aria-label="Permalink to &quot;如何强制使用 WSL Shell&quot;">​</a></h2><p>在 WSL 终端里启动即可：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 方法一：进入 WSL 后启动</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">wsl </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">-</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">d Ubuntu</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">cd </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">mnt</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">d</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">files</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">claude   </span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 或 codex / opencode</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 方法二：一行命令</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">wsl </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">-</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">d Ubuntu </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">-</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">e bash </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">-</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">c </span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">cd /mnt/d/files &amp;&amp; claude</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span></span></code></pre></div><p>这样所有工具都会：</p><ul><li>使用 WSL 的 <code>/bin/bash</code></li><li>路径用 Linux 风格（<code>/mnt/d/files</code>）</li><li>命令通过 WSL 执行</li></ul><h2 id="路径对照" tabindex="-1">路径对照 <a class="header-anchor" href="#路径对照" aria-label="Permalink to &quot;路径对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Windows 路径</th><th>WSL 路径</th></tr></thead><tbody><tr><td>D:\\files</td><td>/mnt/d/files</td></tr><tr><td>C:\\Users\\a1</td><td>/home/a1 (WSL 主目录)</td></tr><tr><td>D:\\devtools</td><td>/mnt/d/devtools</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><strong>Claude Code 不受控制</strong> — 它在 Windows 上永远用 bash，即使你从 PowerShell 启动</li><li><strong>Codex 和 OpenCode 跟随父进程 shell</strong> — 从哪启动就用什么</li><li><strong>WSL 里路径要改</strong> — <code>D:\\files</code> 变成 <code>/mnt/d/files</code></li><li><strong>文件权限不同</strong> — WSL 里的文件权限和 Windows 不一样，注意 git 操作</li><li><strong>性能差异</strong> — WSL 访问 <code>/mnt/c</code>（Windows 盘）比访问 Linux 原生文件系统慢</li></ol>`,36)])])}const g=e(l,[["render",d]]);export{k as __pageData,g as default};
